(function () {
  'use strict';
  // Fix 1: Media Bar queries /Items with isPlayed=False which 500s on 10.11.11
  // Fix 2: Media Bar detail fetches /Items/{id} which 400s on Gelato virtual
  //        items — rewrite to user-scoped /Users/{uid}/Items/{id} (200).
  // Fix 3: Stub window.YT so loadYouTubeAPI() resolves instantly — trailers
  //        are disabled, the external youtube.com script only adds latency.
  // Fix 8 (Aug 26): Media Bar list query asks fields=Id,ImageTags,RemoteTrailers
  //        ONLY → cached list items lack Overview/Genres/ratings → slides
  //        render "No Genre Available"/"No overview available". Expand fields
  //        so list responses carry full metadata, and never serve a sparse
  //        cache entry to a detail fetch.
  // Fix 9 (Aug 26): HSS generates a fresh pageHash per home load → server
  //        recomputes ALL sections (WatchAgain alone 2.2s) → home takes
  //        seconds. Rewrite PageHash to a stable per-user-per-day GUID so the
  //        server cache (24h) + browser cache hit on every visit after the
  //        first of the day.
  // Fix 10 (Aug 26): Media Bar list query — drop MediaSources (0.32s→0.07s)
  //        and add enableTotalRecordCount=false (→0.05s, was 1.03s total).
  // Fix 11 (Aug 26): cast queries (PersonIds) — enableTotalRecordCount=false
  //        (0.8s→0.2s on detail pages).
  // Fix 15 (Aug 26): JFE fetches 5 user-settings files with ?_=Date.now()
  //        cache-busters on EVERY page load. Strip the cache-buster so the
  //        browser HTTP cache can serve them.
  if (!window.YT) {
    window.YT = { Player: function () { return { playVideo(){}, pauseVideo(){}, mute(){}, seekTo(){}, destroy(){} }; } };
  }
  const getUserId = () => {
    try { return window.ApiClient ? window.ApiClient.getCurrentUserId() : null; } catch (e) { return null; }
  };
  const isBareItemDetail = (u) => {
    const m = u.pathname.match(/^\/Items\/([0-9a-f]{32})$/i);
    return m ? m[1] : null;
  };
  const FULL_FIELDS = 'Id,ImageTags,RemoteTrailers,Overview,Genres,CommunityRating,CriticRating,OfficialRating,PremiereDate,RunTimeTicks,ChildCount';
  const hashGuid = (s) => {
    let h1 = 0xdeadbeef, h2 = 0x41c6ce57;
    for (let i = 0; i < s.length; i++) {
      const ch = s.charCodeAt(i);
      h1 = Math.imul(h1 ^ ch, 2654435761);
      h2 = Math.imul(h2 ^ ch, 1597334677);
    }
    h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
    h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
    const hex = (h1 >>> 0).toString(16).padStart(8, '0') + (h2 >>> 0).toString(16).padStart(8, '0');
    const full = (hex + hex).slice(0, 32);
    return full.slice(0, 8) + '-' + full.slice(8, 12) + '-' + full.slice(12, 16) + '-' + full.slice(16, 20) + '-' + full.slice(20, 32);
  };
  const patchUrl = (urlStr) => {
    try {
      const u = new URL(urlStr, window.location.origin);
      if (u.pathname === '/Items' && u.searchParams.has('isPlayed')) {
        u.searchParams.delete('isPlayed');
      }
      // Fix 8+10: expand fields on the Media Bar random list query, drop
      // MediaSources, skip the total-count scan.
      if (u.pathname === '/Items' && u.searchParams.get('sortBy') === 'Random') {
        u.searchParams.set('fields', FULL_FIELDS);
        u.searchParams.set('enableTotalRecordCount', 'false');
      }
      // Fix 11: cast queries don't need the total count (0.8s→0.2s).
      if (u.pathname === '/Items' && u.searchParams.has('PersonIds')) {
        u.searchParams.set('enableTotalRecordCount', 'false');
      }
      // Fix 13: detail-page queries (Seasons/Episodes/Similar/NextUp) don't
      // need the total-count scan either — the client only renders the rows.
      if (/^\/(Shows|Items)\//.test(u.pathname) && /(Seasons|Episodes|Similar|NextUp)$/.test(u.pathname)) {
        u.searchParams.set('enableTotalRecordCount', 'false');
      }
      const itemId = isBareItemDetail(u);
      if (itemId) {
        const uid = getUserId();
        if (uid) {
          u.pathname = '/Users/' + uid + '/Items/' + itemId;
        }
      }
      return u.toString();
    } catch (e) { return urlStr; }
  };
  const SECTION_CACHE_KEY = 'msp-hss-section-cache-v2';
  const SECTION_TTL = 5 * 60 * 1000;
  const getSectionCache = () => { try { return JSON.parse(localStorage.getItem(SECTION_CACHE_KEY) || '{}'); } catch (e) { return {}; } };
  const setSectionCache = (c) => { try { localStorage.setItem(SECTION_CACHE_KEY, JSON.stringify(c)); } catch (e) {} };
  // Fix 14: detail-page response cache (Seasons/Episodes/Similar/NextUp).
  // Repeat visits to a show render instantly instead of re-fetching.
  const DETAIL_CACHE_KEY = 'msp-detail-cache-v1';
  const DETAIL_TTL = 5 * 60 * 1000;
  const getDetailCache = () => { try { return JSON.parse(localStorage.getItem(DETAIL_CACHE_KEY) || '{}'); } catch (e) { return {}; } };
  const setDetailCache = (c) => { try { localStorage.setItem(DETAIL_CACHE_KEY, JSON.stringify(c)); } catch (e) {} };
  const isDetailQuery = (u) => /^\/(Shows|Items)\//.test(u.pathname) && /(Seasons|Episodes|Similar|NextUp)$/.test(u.pathname);
  const origFetch = window.fetch;
  window.fetch = function (input, init) {
    let urlStr = (typeof input === 'string') ? input : (input && input.url) || '';
    try {
      // Fix 9: stable per-user-per-day pageHash for HSS sections.
      if (urlStr.includes('HomeScreen/Sections')) {
        const u = new URL(urlStr, window.location.origin);
        if (u.searchParams.has('PageHash')) {
          const uid = getUserId() || 'anon';
          const day = new Date().toISOString().slice(0, 10);
          u.searchParams.set('PageHash', hashGuid(uid + '|' + day));
          input = u.toString();
        }
      }
      // Fix 15: strip JFE user-settings cache-busters (?_=Date.now()) so the
      // browser HTTP cache can serve them on repeat page loads.
      if (urlStr.includes('/JellyfinEnhanced/user-settings/')) {
        const u = new URL(urlStr, window.location.origin);
        if (u.searchParams.has('_')) {
          u.searchParams.delete('_');
          input = u.toString();
        }
      }
      // Fix 12: cache per-section responses (localStorage, 5 min TTL) so
      // repeat home visits render instantly (WatchAgain alone takes 2.2s
      // server-side). Fresh cache → serve immediately; else fetch + store.
      // FIX12b: the client sends 'AdditionalData' (PascalCase) — searchParams
      // is CASE-SENSITIVE, so reading 'additionalData' returned null for every
      // request → all BecauseYouWatched/Genre rows shared ONE cache key and
      // the first row's movies were served to the second. v2 key ignores
      // stale v1 entries.
      if (urlStr.includes('/HomeScreen/Section/')) {
        const u = new URL(urlStr, window.location.origin);
        const m = u.pathname.match(/\/HomeScreen\/Section\/([^/]+)$/);
        if (m) {
          const extra = u.searchParams.get('AdditionalData') || u.searchParams.get('additionalData') || '';
          const key = (getUserId() || 'anon') + '|' + m[1] + '|' + extra;
          const cache = getSectionCache();
          const hit = cache[key];
          if (hit && Date.now() - hit.t < SECTION_TTL) {
            return Promise.resolve(new Response(JSON.stringify(hit.d), {
              status: 200,
              headers: { 'Content-Type': 'application/json' }
            }));
          }
          return origFetch.call(this, input, init).then((resp) => {
            if (resp && resp.ok) {
              resp.clone().json().then((data) => {
                if (data && Array.isArray(data.Items)) {
                  const c = getSectionCache();
                  c[key] = { t: Date.now(), d: data };
                  setSectionCache(c);
                }
              }).catch(() => {});
            }
            return resp;
          });
        }
      }
      // Fix 14: cache detail-page responses (5 min TTL) — repeat visits to a
      // show render instantly. Fresh cache → serve; else fetch + store.
      // NOTE: patchUrl runs here too so Fix 13 (noTotalCount) applies to
      // these queries even though they return before the /Items block.
      if (urlStr.includes('/Shows/') || urlStr.includes('/Items/')) {
        const u = new URL(urlStr, window.location.origin);
        if (isDetailQuery(u)) {
          const patched = patchUrl(urlStr);
          const key = (getUserId() || 'anon') + '|' + u.pathname + '|' + u.search;
          const dc = getDetailCache();
          const hit = dc[key];
          if (hit && Date.now() - hit.t < DETAIL_TTL) {
            return Promise.resolve(new Response(JSON.stringify(hit.d), {
              status: 200,
              headers: { 'Content-Type': 'application/json' }
            }));
          }
          return origFetch.call(this, patched, init).then((resp) => {
            if (resp && resp.ok) {
              resp.clone().json().then((data) => {
                if (data && (Array.isArray(data.Items) || data.TotalRecordCount !== undefined)) {
                  const c = getDetailCache();
                  c[key] = { t: Date.now(), d: data };
                  setDetailCache(c);
                }
              }).catch(() => {});
            }
            return resp;
          });
        }
      }
      if (urlStr.includes('/Items')) {
        const u = new URL(urlStr, window.location.origin);
        input = patchUrl(urlStr);
        // 5a: cache list responses for later detail serving (full fields now)
        if (isListQuery(u)) {
          return origFetch.call(this, input, init).then((resp) => {
            if (resp && resp.ok) {
              resp.clone().json().then((data) => {
                if (data && Array.isArray(data.Items)) {
                  for (const it of data.Items) {
                    if (it && it.Id) itemCache.set(it.Id, it);
                  }
                }
              }).catch(() => {});
            }
            return resp;
          });
        }
        // 5b: serve detail fetches from cache ONLY when the cached entry has
        // full metadata (else fall through to a real user-scoped fetch).
        const id = detailId(u);
        if (id && itemCache.has(id)) {
          const cached = itemCache.get(id);
          if (cached.Overview || (cached.Genres && cached.Genres.length)) {
            return Promise.resolve(new Response(JSON.stringify(cached), {
              status: 200,
              headers: { 'Content-Type': 'application/json' }
            }));
          }
        }
      }
    } catch (e) { /* fall through */ }
    return origFetch.call(this, input, init);
  };
  const origOpen = XMLHttpRequest.prototype.open;
  XMLHttpRequest.prototype.open = function (m, url) {
    if (typeof url === 'string' && (url.includes('/Items') || url.includes('HomeScreen/Sections'))) {
      url = patchUrl(url);
      if (url.includes('HomeScreen/Sections')) {
        try {
          const u = new URL(url, window.location.origin);
          if (u.searchParams.has('PageHash')) {
            const uid = getUserId() || 'anon';
            const day = new Date().toISOString().slice(0, 10);
            u.searchParams.set('PageHash', hashGuid(uid + '|' + day));
            url = u.toString();
          }
        } catch (e) {}
      }
    }
    return origOpen.call(this, m, url);
  };
  console.log('[MediaBarFix] isPlayed stripped + detail user-scoped + YT stubbed + fields expanded + stable pageHash + noTotalCount');
  // Fix 4: CDN slideshowpure.js hardcodes enableTrailers:true + maxItems:50
  // (plugin WebConfig is never applied to the CDN script). Mutate CONFIG to
  // disable trailers (no SponsorBlock/YouTube work) and shrink the random
  // pool so the pre-warmed exact URLs cover every pick.
  try {
    if (typeof CONFIG !== 'undefined') {
      Object.assign(CONFIG, { enableTrailers: false, maxItems: 10, preloadCount: 1 });
      console.log('[MediaBarFix] CONFIG overridden: trailers off, maxItems 10');
    }
  } catch (e) { console.error('[MediaBarFix] CONFIG override failed:', e); }

  // Fix 5: serve media bar detail fetches from the list-query cache.
  // The slideshow's /Items list query (fields expanded by Fix 8) returns the
  // full slide payload. Serving from cache avoids per-slide network fetches.
  const itemCache = new Map();
  const isListQuery = (u) => u.pathname === '/Items'
    && u.searchParams.get('IncludeItemTypes')
    && u.searchParams.get('sortBy') === 'Random';
  const detailId = (u) => {
    const m = u.pathname.match(/\/([0-9a-f]{32})$/i);
    return m ? m[1] : null;
  };

})();

  // Fix 7 (Aug 20): Jellyfin's NATIVE page spinner (.docspinner.mdl-spinner)
  // gets stuck mdlSpinnerActive when a home/library request 500s (the
  // /Items EF Core NullReference on isPlayed combos) — leaving a spinning
  // circle over the hero forever. Hide it permanently.
  (function () {
    const css = document.createElement('style');
    css.textContent = '.docspinner.mdl-spinner, .mdl-spinner.docspinner { display:none !important; visibility:hidden !important; }';
    document.head.appendChild(css);
    const kill = () => {
      const el = document.querySelector('.docspinner.mdl-spinner');
      if (el) { el.classList.remove('mdlSpinnerActive'); el.style.display = 'none'; }
    };
    kill();
    if (window.MutationObserver) {
      new MutationObserver(kill).observe(document.body, { childList: true, subtree: true });
    }
  })();

(function() {
  if (document.getElementById('msp-detail-polish-css')) return;
  var link = document.createElement('link');
  link.id = 'msp-detail-polish-css';
  link.rel = 'stylesheet';
  link.type = 'text/css';
  link.href = '/jellyfin-assets/detail-polish.css?v=1';
  document.head.appendChild(link);
})();

(function() {
  if (document.getElementById('msp-home-polish-css')) return;
  var link = document.createElement('link');
  link.id = 'msp-home-polish-css';
  link.rel = 'stylesheet';
  link.type = 'text/css';
  link.href = '/jellyfin-assets/home-polish.css?v=1';
  document.head.appendChild(link);
})();

